458	func measureL7(unreach string, cycles int, timeout time.Duration) l7Result {
459		// Warm up so lazily created runtime goroutines are in the baseline.
460		trace(context.Background(), unreach, 3, timeout, hardDeadline)
461		time.Sleep(200 * time.Millisecond)
462		l := l7Result{Cycles: cycles, FdBefore: countFds(), GoBefore: runtime.NumGoroutine(), MinPending: 1 << 30}
463		l.FdMax, l.GoMax = l.FdBefore, l.GoBefore
464		for i := 0; i < cycles; i++ {
465			ctx, cancel := context.WithCancel(context.Background())
466			var cancelledAt time.Time
467			go func() {
468				time.Sleep(150 * time.Millisecond)
469				cancelledAt = time.Now()
470				cancel()
471			}()
472			r := trace(ctx, unreach, hardMaxTTL, timeout, hardDeadline)
473			end := time.Now()
474			cancel()
475			// cancelledAt is written before cancel() and read after trace
476			// returned because of that cancel(), so it is ordered.
477			if cancelledAt.IsZero() || r.Outcome != outCancelled {
478				l.Err = fmt.Sprintf("cycle %d: trace ended with %q before cancellation", i, r.Outcome)
479			} else {
480				l.Stops = append(l.Stops, end.Sub(cancelledAt))
481			}
482			if r.Pending < l.MinPending {
483				l.MinPending = r.Pending
484			}
485			l.FdMax = max(l.FdMax, countFds())
486			l.GoMax = max(l.GoMax, runtime.NumGoroutine())
487		}
488		time.Sleep(200 * time.Millisecond)
489		l.FdAfter, l.GoAfter = countFds(), runtime.NumGoroutine()
490		return l
491	}
