540	func (r *report) printTrace(title string, t result) {
541		r.f("--- %s: %s ---\n", title, t.Target)
542		r.f("max TTL %d, probe timeout %s, duration %s, result: %s\n", t.MaxTTL, t.Timeout, t.Duration.Round(time.Millisecond), t.Outcome)
