547				addr = p.Addr.String()
548			}
549			lat := "-"
550			if p.Latency > 0 {
551				lat = fmt.Sprintf("%.2fms", float64(p.Latency.Microseconds())/1000)
552			}
553			extra := p.Kind.String()
554			if p.Kind == kindUnreach {
555				extra = fmt.Sprintf("unreachable (icmp %d/%d)", p.Code/1000, p.Code%1000)
556			}
557			if p.SockOpt != "" {
558				extra += " setsockopt-error: " + p.SockOpt
559			}
560			if p.Kind == kindSockErr {
561				extra += " detail: " + p.Detail
562			}
563			r.f("%-4d %-16s %-10s %s\n", p.TTL, addr, lat, extra)
564		}
565		r.f("\n")
566	}
