588	func median(d []time.Duration) time.Duration {
589		if len(d) == 0 {
590			return 0
591		}
592		s := append([]time.Duration(nil), d...)
593		sort.Slice(s, func(i, j int) bool { return s[i] < s[j] })
594		return s[len(s)/2]
595	}
