597	func (r *report) printL7(l l7Result) {
598		r.f("--- L7 measurement ---\n")
599		r.f("cycles: %d (cancelled 150ms after start, unresolved probes at cancel: min %d)\n", l.Cycles, l.MinPending)
600		r.f("fds       before %d, max during %d, after %d\n", l.FdBefore, l.FdMax, l.FdAfter)
601		r.f("goroutines before %d, max during %d, after %d\n", l.GoBefore, l.GoMax, l.GoAfter)
602		if len(l.Stops) > 0 {
603			s := append([]time.Duration(nil), l.Stops...)
604			sort.Slice(s, func(i, j int) bool { return s[i] < s[j] })
605			r.f("stop delay after cancel: min %s, median %s, max %s\n", s[0], median(s), s[len(s)-1])
606		}
607		if l.Err != "" {
608			r.f("error: %s\n", l.Err)
609		}
610		r.f("\n")
611	}
