622	func (r *report) verdicts(m result, l6 l6Result, l5 l5Result, extras []result, l7 l7Result) {
623		r.f("=== Verdicts of this run ===\n")
624	
625		// L1 (binary side). The os/exec import and the empty-PATH run are checked outside.
626		sockOptErr := ""
627		for _, t := range append([]result{m, l5.Unreach}, extras...) {
628			for _, p := range t.Probes {
629				if p.SockOpt != "" && sockOptErr == "" {
630					sockOptErr = p.SockOpt
631				}
632			}
633		}
634		l1 := os.Geteuid() != 0 && capEff() == "0000000000000000" && sockOptErr == ""
635		r.f("L1 %s  uid=%d CapEff=%s setsockopt-error=%q (os/exec import and empty-PATH run are checked outside the binary)\n", ok(l1), os.Geteuid(), capEff(), sockOptErr)
636	
637		// L2.
638		answered, ordered, prev := 0, true, 0
639		for _, p := range m.Hops {
640			if p.Addr.IsValid() && (p.Kind == kindTimeExceed || p.Kind == kindReached || p.Kind == kindUnreach) {
641				answered++
642				if p.TTL <= prev {
643					ordered = false
644				}
645				prev = p.TTL
646			}
647		}
648		r.f("L2 %s  %d hops with an address (need >= 3), increasing TTL order: %v\n", ok(answered >= 3 && ordered), answered, ordered)
649	
650		// L3: replied probes woke up long before the read deadline.
651		maxLat, replied := time.Duration(0), 0
652		for _, p := range m.Probes {
653			if p.Addr.IsValid() {
654				replied++
655				maxLat = max(maxLat, p.Latency)
656			}
657		}
658		l3 := replied > 0 && maxLat < m.Timeout/2
659		r.f("L3 %s  netpoller (RawConn.Read, no polling loop): %d replies, max wait %s vs read deadline %s\n", ok(l3), replied, maxLat.Round(time.Microsecond), m.Timeout)
660	
661		// L4: a silent TTL followed by a TTL that answers, on any traced path.
662		l4src := ""
663		for _, t := range append([]result{m}, extras...) {
664			if hasSilentThenAnswer(t) {
665				l4src = t.Target
666				break
667			}
668		}
669		if l4src != "" {
670			r.f("L4 OK  silent hop followed by an answering hop on the path to %s\n", l4src)
671		} else {
672			r.f("L4 NOT EVALUATED  no silent hop followed by an answering hop on the traced paths\n")
673		}
674	
675		// L5.
676		l5ok := l5.Unreach.Outcome == outTTLMax && l5.Unreach.Duration <= hardDeadline &&
677			l5.TTLBound.Outcome == outTTLMax && l5.ShortDead.Outcome == outDelay && l5.ShortDead.Duration <= hardDeadline
678		r.f("L5 %s  unreachable: %s in %s; TTL max: %s in %s; delay: %s in %s\n", ok(l5ok),
679			l5.Unreach.Outcome, l5.Unreach.Duration.Round(time.Millisecond),
680			l5.TTLBound.Outcome, l5.TTLBound.Duration.Round(time.Millisecond),
681			l5.ShortDead.Outcome, l5.ShortDead.Duration.Round(time.Millisecond))
682	
683		// L6.
684		r.f("L6 %s  %s (threshold %s, real path: %v, bound: %d)\n", ok(l6.Run.Duration < l6.Threshold), l6.Run.Duration.Round(time.Millisecond), l6.Threshold, l6.Real, l6.Bound)
685	
686		// L7.
687		l7ok := l7.Err == "" && l7.FdAfter == l7.FdBefore && l7.GoAfter == l7.GoBefore && l7.FdMax <= l7.FdBefore && l7.MinPending >= 1
688		r.f("L7 %s  fds %d -> %d (max %d), goroutines %d -> %d, %d cycles\n", ok(l7ok), l7.FdBefore, l7.FdAfter, l7.FdMax, l7.GoBefore, l7.GoAfter, l7.Cycles)
689		r.f("=== end of report ===\n")
690	}
