692	func hasSilentThenAnswer(t result) bool {
693		silent := false
694		for _, p := range t.Hops {
695			switch {
696			case p.Kind == kindSilent:
697				silent = true
698			case silent && p.Addr.IsValid():
699				return true
700			}
701		}
702		return false
703	}
